"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["81363"],{41991(e){e.exports=JSON.parse('{"id":"F500","slug":"greenwashing-alignment-gap","name":"Greenwashing Check: Claimed vs Aligned Share","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"Greenwashing","level":"Beginner","aliases":["greenwashing","taxonomy alignment","green revenue share","claim gap","green claims"],"formula":{"latex":"A=\\\\frac{\\\\sum \\\\text{Aligned revenue}}{\\\\text{Total revenue}},\\\\quad \\\\text{Gap}=C-A","also":[],"text":"Aligned share = revenue from activities that meet an official green taxonomy criteria / total revenue; Claim gap = share claimed in marketing - aligned share; Overstatement ratio = claimed share / aligned share; Fund version: share of holdings that meet the fund\'s stated sustainability criteria vs share claimed"},"symbols":[{"symbol":"A","meaning":"Share of revenue (or holdings) that meets the taxonomy criteria","unit":"percent"},{"symbol":"C","meaning":"Share the company or fund claims is green","unit":"percent"}],"when_to_use":"Use it to compare what a firm or a fund says with what can be verified. A large gap between the claimed green share and the share that meets a recognized taxonomy is a warning of greenwashing. Regulators in several places require evidence for green claims. A small gap does not prove the claims are right, since the taxonomy has limits too.","worked_example":{"problem":"A company with 2,400 million revenue claims that 60% of its business is green. Activities that meet the taxonomy bring in 300 million and 180 million.","inputs":{"t":2400,"a":[300,180],"c":60},"steps":[{"label":"Aligned share","working":null,"value":"20.0%"},{"label":"Claim gap (percentage points)","working":"(0.6-0.2) x 100","value":"40.0"},{"label":"Claim / aligned share","working":"0.6 / 0.2","value":"3.00"},{"label":"Flag (1 = gap above 10 points)","working":"1 if (0.6-0.2)>0.10 else 0","value":"1"}],"answer":"The aligned share is 20.0%. The claimed share is 60%, so the gap is 40.0 percentage points, and the claim is 3.00 times the aligned share. The flag is 1 (1 = claim is more than 10 percentage points above the aligned share)."},"calculator":{"available":true,"inputs":[{"id":"t","label":"Total revenue","unit":"money","type":"number","default":2400,"hint":""},{"id":"a","label":"Aligned revenue by activity","unit":"money","type":"list","default":[300,180],"hint":""},{"id":"c","label":"Claimed green share","unit":"%","type":"number","default":60,"hint":""}],"checks":[{"expr":"t>0 and sum(a)<=t","message":"Total revenue must be above zero and aligned revenue cannot exceed it."}],"steps":[{"id":"a_","label":"Aligned share","expr":"sum(a)/t","format":"pct1"},{"id":"gap","label":"Claim gap (percentage points)","expr":"(c-a_)*100","format":"num1"},{"id":"mult","label":"Claim / aligned share","expr":"c/a_","format":"num2"},{"id":"flag_","label":"Flag (1 = gap above 10 points)","expr":"1 if (c-a_)>0.10 else 0","format":"num0"}],"results":["a_","gap","mult","flag_"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"a_":0.2,"gap":40,"mult":2.9999999999999996,"flag_":1}},"finder":{"finds":"How far a green claim runs ahead of the evidence","needs":"Total revenue, aligned revenue, claimed share"},"related":[{"slug":"esg-rating-divergence","name":"ESG Rating Divergence Between Providers"},{"slug":"social-return-on-investment","name":"Impact Investing: Social Return on Investment"},{"slug":"weighted-average-carbon-intensity","name":"Climate Disclosure: Carbon Intensity and Financed Emissions"}],"related_ids":["F495","F497","F498"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>A</mi><mo>=</mo><mfrac><mrow><mo>\u2211</mo><mtext>Aligned\xa0revenue</mtext></mrow><mtext>Total\xa0revenue</mtext></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Gap</mtext><mo>=</mo><mi>C</mi><mo>\u2212</mo><mi>A</mi></mrow><annotation encoding=\\"application/x-tex\\">A=\\\\frac{\\\\sum \\\\text{Aligned revenue}}{\\\\text{Total revenue}},\\\\quad \\\\text{Gap}=C-A</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>A</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle A</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mfrac><mrow><mo>\u2211</mo><mtext>Aligned\xa0revenue</mtext></mrow><mtext>Total\xa0revenue</mtext></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\frac{\\\\sum \\\\text{Aligned revenue}}{\\\\text{Total revenue}}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Gap</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Gap}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>C</mi><mo>\u2212</mo><mi>A</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =C-A</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"greenium-and-step-up","name":"Green Bonds: Greenium Saving and Sustainability-Linked Step-Up Cost"},"next":{"slug":"growing-perpetuity","name":"Growing Perpetuity"},"lesson":null,"total":522}')}}]);